def estimator_cov(self,method):
        """ Creates covariance matrix for the estimators

        Parameters
        ----------
        method : str
            Estimation method

        Returns
        ----------
        A Covariance Matrix
        """
        if method == 'MLE':
            return self.estimator_cov_MLE()
        elif method == 'ML':
            return self.estimator_cov_ML()
        elif method == 'PML':
            return self.estimator_cov_PML()
        else:
            raise ValueError('method must be either MLE or ML')

